def solve(coins, amount):
    """
    Return the minimum number of coins needed to make `amount` using unlimited
    supply of denominations in `coins`. If impossible, return -1.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    if not coins:
        return -1

    # Initialize DP array: dp[i] = min coins to make amount i
    INF = amount + 1  # any value > amount is effectively infinity
    dp = [INF] * (amount + 1)
    dp[0] = 0

    for coin in coins:
        if coin <= 0:
            continue  # ignore non-positive denominations
        for i in range(coin, amount + 1):
            if dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1

    return dp[amount] if dp[amount] != INF else -1
